H=W=20
g=[[0]*W for _ in range(H)]
# original rectangle
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
markers=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in markers:g[r][c]=1
# extend along rows of rectangle away from marker; unrestricted if none
for r in range(2,9):
    ms=[c for rr,c in markers if rr==r]
    if not ms:
        for c in range(W):
            if g[r][c]==0:g[r][c]=2
    else:
        # assumed single marker: fill side opposite its direction from rectangle
        m=ms[0]
        if m < 9: ran=range(9,W)
        elif m > 15: ran=range(0,16)
        else: ran=range(W)
        for c in ran:
            if g[r][c]==0:g[r][c]=2
# vertical extension top always; bottom only if no blocker in that column
for c in range(9,16):
    below=[r for r,cc in markers if cc==c and r>8]
    for r in range(0,2):
        if g[r][c]==0:g[r][c]=2
    if not below:
        for r in range(9,H):
            if g[r][c]==0:g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))
